"""Write the ordinary Zhaofeng gate page to the Shanghai project root or a staging directory."""
from pathlib import Path
import argparse

HTML = '<!DOCTYPE html>\n\n<html lang="zh-CN">\n<head>\n<meta charset="utf-8"/>\n<meta content="width=device-width,initial-scale=1" name="viewport"/>\n<title>兆丰别墅日升纹入口三维模型</title>\n<link href="assets/favicon.svg" rel="icon"/>\n<link href="src/dacheng-hall.css" rel="stylesheet"/>\n<style>\n    .panel label:not(:first-child) {margin-top:10px}\n    button[aria-pressed=true] {outline:1px solid #d6e6d4;outline-offset:1px}\n    select:disabled {opacity:.58}\n    @media(max-width:650px) {\n      body {display:grid;grid-template-rows:auto minmax(240px,44svh) auto auto;min-height:100svh}\n      header,.panel,footer,#model-view {position:static}\n      header {padding:10px 16px 5px}\n      #model-view {min-width:0;overflow:hidden}\n      .panel {margin:0 10px;max-height:none;overflow:visible}\n      footer {padding:6px 16px}\n    }\n  </style>\n<script type="importmap">{"imports":{"three":"./vendor/three.module.js"}}</script>\n</head>\n<body>\n<header><a href="landmarks.html">← 上海历史建筑目录</a>\n<p class="eyebrow">长宁区 · 长宁路712弄</p><h1>兆丰别墅日升纹入口</h1></header>\n<main aria-label="兆丰别墅日升纹入口三维模型" id="model-view"></main>\n<aside aria-label="观察机位与模型下载" class="panel">\n<p class="scope">从街上可以同时看见入口两边的壁灯和朝弄内敞开的铁门。东侧题名墙的阶梯形轮廓围着半日与放射纹样，下方排列四个铸字和突出的横向线脚。</p>\n<label for="detail">模型细节</label>\n<select id="detail"><option value="auto">随距离切换</option><option value="full">完整近景</option><option value="lod">简化远景</option></select>\n<div aria-label="摄影与模型机位" class="buttons" id="model-cameras"></div>\n<button hidden id="retry" type="button">重新加载</button>\n<p aria-live="polite" id="status" role="status">正在读取模型…</p>\n<div aria-label="下载模型" class="downloads" id="downloads"></div>\n<p><a download href="assets/models/candidates/changning-zhaofeng-villas-sunburst-entry/changning-zhaofeng-villas-sunburst-entry-source.zip" id="download-source">下载可重建模型的 Python 源码包（ZIP）</a></p>\n<p><a href="data/audit/zhaofeng-villas-sunburst-entry-v1/final/registration/registered-views.jpg" target="_blank" rel="noopener">四处摄影机位对照</a> · <a href="data/audit/zhaofeng-villas-sunburst-entry-v1/final/registration/district-detail-model.jpg" target="_blank" rel="noopener">区政府题名墙近照机位</a> · <a href="data/audit/zhaofeng-villas-sunburst-entry-v1/final/registration/opposite-detail-model.jpg" target="_blank" rel="noopener">题名墙反向近照机位</a> · <a href="data/audit/zhaofeng-villas-sunburst-entry-v1/final/registration/road-anniversary-model.jpg" target="_blank" rel="noopener">周年报道的街前机位</a> · <a href="data/audit/zhaofeng-villas-sunburst-entry-v1/final/registration/street-station-7-model.jpg" target="_blank" rel="noopener">2021年1月路南第7站</a></p>\n<p>长宁区政府记载，兆丰别墅位于长宁路712弄，得名于西侧的兆丰公园。这里的住宅分期兴建。三维模型展示临街入口、题名墙及墙前花台。<a href="https://www.shcn.gov.cn/col6991/20210506/871962.html">长宁区政府图文与题名墙照片</a></p>\n<p>摄影位依据2021年1月的街景、同年发表的两组报道照片以及另一张题名墙照片配准。报道日期与拍摄日期分别记录。<a href="http://sh.people.com.cn/n2/2021/1002/c134768-34942337.html">人民网周年报道</a> · <a href="https://baike.baidu.com/item/兆丰别墅/2785237">反向题名墙照片</a> · <a href="source/precise/changning-zhaofeng-villas-sunburst-entry/measurements/registered-views.json">六个摄影机位的投影与依据</a></p>\n</aside><footer>拖动旋转 · 滚轮或双指缩放</footer>\n<script src="source/precise/changning-zhaofeng-villas-sunburst-entry/source/viewer.js" type="module"></script>\n</body></html>\n'

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(HTML, encoding="utf-8")

if __name__ == "__main__":
    main()
